import { profileSelector } from './profile-view.js';
import { escapeHtml as e, time } from './store.js';
import { spanAttempts, comparisonPair, diffWords } from './evidence.js';
import { jobAttempts } from './activity-store.js';
const button = (action, label, id, cls = '', attrs = '') => `<button class="button ${cls}" data-action="${action}" data-id="${e(id)}" ${attrs}>${label}</button>`;
const field = (label, value) => `<div><dt>${label}</dt><dd>${e(value ?? '—')}</dd></div>`;
const range = r => `${time(r[0])}–${time(r[1])}`;
export function comparisonView(s, job) {
  const spans = job.spanIds.map(id => s.spans.find(p => p.id === id)), span = spans.find(p => p.id === s.selectedSpanId) || spans[0];
  if (!span) return '<div class="technical-empty">This job has no audio spans to compare.</div>';
  const candidates = spanAttempts(s, span.id), [left, right] = comparisonPair(s, span.id), diff = diffWords(left?.resultText || '', right?.resultText || '');
  const both = left?.state === 'Succeeded' && right?.state === 'Succeeded';
  const preferred = s.preferredEvidence[span.id];
  const select = (side, selected) => `<label>${side === 'left' ? 'Attempt A' : 'Attempt B'}<select data-compare-side="${side}" data-span="${span.id}"><option value="">Select attempt</option>${candidates.map(a => `<option value="${a.id}" ${a.id === selected?.id ? 'selected' : ''}>${e(a.id)} · ${e(a.model)} · ${e(a.state)} · ${e(a.jobId)}</option>`).join('')}</select></label>`;
  const column = (attempt, tokens, name) => `<article class="comparison-column ${preferred === attempt?.id && attempt ? 'is-preferred' : ''}"><header><div><span class="overline">${name}</span><h3>${e(attempt?.id || 'No attempt selected')}</h3></div>${attempt ? `<span class="status-label status-${attempt.state.toLowerCase()}"><i></i>${e(attempt.state)}</span>` : ''}</header>${attempt ? `<dl class="comparison-metadata">${field('Model', attempt.model)}${field('Job', attempt.jobId)}${field('Input window', range(attempt.input))}${field('Blob', attempt.blobId)}${field('Context', attempt.contextId)}${field('Duration', attempt.elapsedMs ? (attempt.elapsedMs / 1000).toFixed(2) + ' s' : 'Pending')}</dl><div class="comparison-text">${attempt.resultText ? tokens.map(t => `<span class="${both && t.changed ? name === 'A' ? 'diff-removed' : 'diff-added' : ''}">${e(t.text)}</span>`).join('') : attempt.error ? `<div class="comparison-error"><strong>${e(attempt.error.code)}</strong><p>${e(attempt.error.message)}</p><small>No final hypothesis available.</small></div>` : '<span class="muted">Awaiting final recognition result.</span>'}</div><footer>${preferred === attempt.id ? '<span class="badge green">Preferred evidence</span>' : ''}${button('activity-reference', 'Inspect execution', attempt.id, 'text-button small-button')}</footer>` : '<div class="technical-empty">Select another attempt for this span.</div>'}</article>`;
  return `<section class="comparison-view"><div class="comparison-toolbar"><label>Target span<select id="comparison-span">${spans.map(p => `<option value="${p.id}" ${p.id === span.id ? 'selected' : ''}>${e(p.id)} · ${range(p.target)}</option>`).join('')}</select></label><div class="compare-scope">${candidates.length} attempts across ${new Set(candidates.map(a => a.jobId)).size} jobs<br><strong>Same target · independent inputs</strong></div></div><div class="comparison-selectors">${select('left', left)}${select('right', right)}</div>${left && right ? `<div class="comparison-controls-summary"><span>${left.model === right.model ? 'Same model' : 'Model differs'}</span><span>${left.blobId === right.blobId ? 'Same audio blob' : 'Audio input differs'}</span><span>${left.contextId === right.contextId ? 'Same frozen context' : 'Context snapshot differs'}</span></div>` : ''}<div class="comparison-summary">${both ? diff.bounded ? 'Long transcripts: full text shown; token highlighting limited to 700 words per result.' : diff.added || diff.removed ? `<span class="diff-count removed">${diff.removed} removed</span><span class="diff-count added">${diff.added} added</span><span>Word differences · A → B</span>` : 'Recognition text matches.' : 'Select two successful attempts to compare text. Failed and pending attempts remain inspectable.'}</div><div class="comparison-columns">${column(left, diff.left, 'A')}${column(right, diff.right, 'B')}</div><div class="comparison-policy"><strong>Source choice and document acceptance are separate decisions.</strong><span>Resolve conflicting evidence in Review. Recognition controls belong to the Dictation view.</span></div></section>`;
}
export function retryForm(s) {
  const job = s.jobs.find(j => j.id === s.selectedJobId), span = s.spans.find(p => p.id === s.retrySpanId);
  const previous = jobAttempts(s, job.id).filter(a => a.spanId === span.id).at(-1), audio = s.audioAssets.find(a => a.id === span.audioId);
  const before = previous ? span.target[0] - previous.input[0] : 6, after = previous ? previous.input[1] - span.target[1] : 6;
  return `<div class="retry-target"><span>Target span</span><strong>${e(span.id)} · ${range(span.target)}</strong><small>${e(job.id)} · ${e(audio.name)}</small></div><label class="setting-field"><span>Run configuration</span><select id="attempt-config"><option value="original">Reuse original frozen configuration · ${e(previous?.model || job.model)}</option><option value="current">Freeze a current recognizer profile and primer</option></select></label><div id="retry-profile-controls" hidden><label class="setting-field"><span>Recognizer profile</span>${profileSelector(s, 'recognizer', job.dictationId, 'attempt-profile')}</label></div><label class="setting-field"><span>Audio input</span><select id="attempt-audio"><option value="same">${previous ? 'Reuse exact blob · ' + e(previous.blobId) : 'Prepare default input window'}</option><option value="custom">Prepare a new window</option></select></label><div class="setting-grid" id="attempt-padding" hidden><label class="setting-field"><span>Evidence before (seconds)</span><input id="attempt-before" type="number" min="0" max="120" value="${before}"/></label><label class="setting-field"><span>Evidence after (seconds)</span><input id="attempt-after" type="number" min="0" max="120" value="${after}"/></label></div><div class="retry-window-preview" id="retry-window-preview">${previous ? 'Exact input ' + range(previous.input) + ' · ' + (previous.input[1] - previous.input[0]) + ' seconds' : 'Input is clipped to available audio; target remains fixed.'}</div><div class="quiet-note">${previous ? 'Retry of ' + e(previous.id) + '. ' : ''}Earlier attempts are preserved. This action queues a new execution; it does not insert text.</div>`;
}
